declare(strict_types=1);

namespace App\Jobs;

use BotGate\Client;
use BotGate\Exception\BotGateException;
use BotGate\Exception\RateLimitException;
use BotGate\Exception\TelegramException;
use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Foundation\Bus\Dispatchable;
use Illuminate\Queue\InteractsWithQueue;
use Illuminate\Queue\SerializesModels;
use Illuminate\Support\Facades\Log;
use RuntimeException;

final class SendTelegramNotification implements ShouldQueue
{
    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;

    public int $tries = 4;
    public int $maxExceptions = 1;
    public int $timeout = 40;
    public bool $failOnTimeout = true;

    public function __construct(
        public readonly string $notificationId,
        public readonly string $botId,
        public readonly string $chatId,
        public readonly string $text,
    ) {}

    public function handle(Client $client): void
    {
        try {
            $client->bot($this->botId)->call('sendMessage', [
                'chat_id' => $this->chatId,
                'text' => $this->text,
            ]);
        } catch (RateLimitException $error) {
            $this->releaseAfterLimit($error->retryAfter(), 'botgate');
            return;
        } catch (TelegramException $error) {
            if ($error->telegramErrorCode() === 429) {
                $this->releaseAfterLimit($error->retryAfter(), 'telegram');
            } else {
                Log::warning('Telegram rejected notification', [
                    'notification_id' => $this->notificationId,
                    'telegram_error_code' => $error->telegramErrorCode(),
                ]);
                $this->fail(new RuntimeException('Telegram отклонил запрос: проверьте параметры и права бота.'));
            }
            return;
        } catch (BotGateException $error) {
            Log::warning('Telegram notification stopped', [
                'notification_id' => $this->notificationId,
                'http_status' => $error->httpStatusCode(),
            ]);

            $this->fail(new RuntimeException('Отправка остановлена; проверьте результат перед повтором.'));
            return;
        }

        Log::info('Telegram notification sent', [
            'notification_id' => $this->notificationId,
        ]);
    }

    private function releaseAfterLimit(?int $wait, string $source): void
    {
        Log::notice('Telegram notification rate limited', [
            'notification_id' => $this->notificationId,
            'source' => $source,
            'retry_after' => $wait,
        ]);

        if ($wait === null || $wait < 0) {
            $this->fail(new RuntimeException('Лимит без времени ожидания: требуется разбор.'));
            return;
        }

        $this->release(max(1, $wait) + random_int(1, 3));
    }
}

