declare(strict_types=1);

use BotGate\Client;
use BotGate\Config;

require __DIR__.'/vendor/autoload.php';

$requiredEnv = static function (string $name): string {
    $value = getenv($name);
    if ($value === false || trim($value) === '') {
        throw new RuntimeException('Не задана переменная '.$name);
    }

    return $value;
};

$client = Client::fromConfig(new Config(
    apiKey: $requiredEnv('BOTGATE_API_KEY'),
    timeout: 20.0,
    maxRetries: 0,
));

$bot = $client->bot($requiredEnv('BOTGATE_BOT_ID'));

