declare(strict_types=1);

use BotGate\Exception\BotGateException;
use BotGate\Exception\RateLimitException;
use BotGate\Exception\TelegramException;
use BotGate\Exception\TransportException;

require __DIR__.'/bootstrap.php';

try {
    $response = $bot->call('sendMessage', [
        'chat_id' => $requiredEnv('TELEGRAM_CHAT_ID'),
        'text' => 'Проверка уведомлений из PHP',
    ]);

    $result = is_array($response->result) ? $response->result : [];
    echo 'Отправлено. message_id: '.($result['message_id'] ?? 'не указан')."\n";
} catch (RateLimitException $error) {
    $wait = $error->retryAfter();
    fwrite(STDERR, 'Лимит BotGate. Ожидание: '.($wait ?? 'не указано')." секунд\n");
    exit(1);
} catch (TelegramException $error) {
    if ($error->telegramErrorCode() === 429) {
        $wait = $error->retryAfter();
        fwrite(STDERR, 'Лимит Telegram. Ожидание: '.($wait ?? 'не указано')." секунд\n");
    } else {
        fwrite(STDERR, 'Telegram отклонил запрос, код '.($error->telegramErrorCode() ?? 'не указан').". Проверьте параметры и права бота.\n");
    }
    exit(1);
} catch (TransportException $error) {
    fwrite(STDERR, "Сбой соединения. Результат отправки неизвестен; проверьте чат и журнал.\n");
    exit(1);
} catch (BotGateException $error) {
    fwrite(STDERR, 'Запрос остановлен, HTTP '.$error->httpStatusCode().". Проверьте настройки и ответ API.\n");
    exit(1);
}

declare(strict_types=1);

use BotGate\Http\MultipartField;

require __DIR__.'/bootstrap.php';

$stream = fopen(__DIR__.'/example.txt', 'rb');
if ($stream === false) {
    throw new RuntimeException('Не удалось открыть тестовый файл.');
}

try {
    $bot->callMultipart('sendDocument', [
        MultipartField::field('chat_id', $requiredEnv('TELEGRAM_CHAT_ID')),
        MultipartField::file('document', $stream, 'example.txt', 'text/plain'),
        MultipartField::field('caption', 'Тестовый документ из PHP'),
    ]);
} finally {
    if (is_resource($stream)) {
        fclose($stream);
    }
}

declare(strict_types=1);

use BotGate\DTO\Update;
use BotGate\Webhook\SignatureValidator;

function decodeBotGateUpdate(string $body, string $signature, string $secret): Update
{
    if ($secret === '') {
        throw new RuntimeException('Webhook Secret не настроен.');
    }

    (new SignatureValidator($secret))->validate($body, $signature);
    $update = Update::fromJson($body);

    if (!is_int($update->payload['update_id'] ?? null)) {
        throw new UnexpectedValueException('Отсутствует корректный update_id.');
    }

    return $update;
}

