/**
 * @return array{state: string, after_seconds: ?int}
 */
function telegramResponseDecision(int $httpStatus, ?string $body): array
{
    $unknown = ['state' => 'unknown', 'after_seconds' => null];
    if ($body === null || $httpStatus < 200 || $httpStatus >= 500) {
        return $unknown;
    }

    try {
        $response = json_decode($body, true, 512, JSON_THROW_ON_ERROR);
    } catch (JsonException) {
        return $unknown;
    }
    if (!is_array($response)) {
        return $unknown;
    }
    if ($httpStatus < 300 && ($response['ok'] ?? null) === true) {
        return ['state' => 'sent', 'after_seconds' => null];
    }

    $code = $response['error_code'] ?? null;
    if (($response['ok'] ?? null) !== false || !is_int($code) || $code < 1 || $code >= 500) {
        return $unknown;
    }
    if ($code !== 429) {
        return ['state' => 'failed', 'after_seconds' => null];
    }

    $parameters = is_array($response['parameters'] ?? null) ? $response['parameters'] : [];
    $wait = $parameters['retry_after'] ?? null;
    if (!is_int($wait) || $wait < 0 || $wait > PHP_INT_MAX - 3) {
        return ['state' => 'paused', 'after_seconds' => null];
    }

    return [
        'state' => 'retry',
        'after_seconds' => max(1, $wait) + random_int(1, 3),
    ];
}

