use BotGate\Exception\BotGateException;
use BotGate\Exception\RateLimitException;
use BotGate\Exception\TelegramException;

/**
 * @return array{state: string, source: ?string, after_seconds: ?int}
 */
function telegramFailureDecision(BotGateException $error): array
{
    if ($error instanceof RateLimitException) {
        $source = 'botgate';
        $wait = $error->retryAfter();
    } elseif ($error instanceof TelegramException) {
        if ($error->telegramErrorCode() !== 429) {
            return ['state' => 'failed', 'source' => 'telegram', 'after_seconds' => null];
        }

        $source = 'telegram';
        $wait = $error->retryAfter();
    } else {
        $status = $error->httpStatusCode();
        $state = $status >= 400 && $status < 500 ? 'failed' : 'unknown';

        return ['state' => $state, 'source' => null, 'after_seconds' => null];
    }

    if ($wait === null || $wait < 0) {
        return ['state' => 'paused', 'source' => $source, 'after_seconds' => null];
    }

    return [
        'state' => 'retry',
        'source' => $source,
        'after_seconds' => max(1, $wait) + random_int(1, 3),
    ];
}

