declare(strict_types=1);

function enqueueTelegramNotification(
    PDO $db,
    string $botId,
    int $updateId,
    string $operationKey,
    string $chatId,
    string $text,
): string {
    if ($botId === '' || $updateId < 0 || $operationKey === '' || $chatId === '' || $text === '') {
        throw new InvalidArgumentException('Не заданы данные события или уведомления.');
    }

    $db->beginTransaction();
    try {
        $inbox = $db->prepare(
            'INSERT INTO telegram_inbox (bot_id, update_id) VALUES (?, ?)
             ON CONFLICT (bot_id, update_id) DO NOTHING'
        );
        $inbox->execute([$botId, $updateId]);
        if ($inbox->rowCount() === 0) {
            $db->commit();
            return 'duplicate_update';
        }

        $notification = $db->prepare(
            'INSERT INTO telegram_notifications (bot_id, operation_key, chat_id, message_text)
             VALUES (?, ?, ?, ?)
             ON CONFLICT (bot_id, operation_key) DO NOTHING'
        );
        $notification->execute([$botId, $operationKey, $chatId, $text]);
        $created = $notification->rowCount() === 1;
        $db->commit();

        return $created ? 'queued' : 'already_queued';
    } catch (Throwable $error) {
        if ($db->inTransaction()) {
            $db->rollBack();
        }
        throw $error;
    }
}

